红细胞计数": "3.2 × 10^12/L［参考值：4.0-5.0 × 10^12/L］", "血小板计数": "468 × 10^9/L［参考值：150-400 × 10^9/L］", "血尿素氮": "5.5 mmol/L［参考值：2.9-8.2 mmol/L］", "血氯": "102 mmol/L［参考值：98-106 mmol/L］", "血清总胆红素": "12 μmol/L［参考值：3.4-20.5 μmol/L］", "血清总蛋白": "68 g/L［参考值：60-80 g/L］", "血清白蛋白": "42 g/L［参考值：35-50 g/L］", "血清肌酐": "70 μmol/L［参考值：44-97 μmol/L］", "血白细胞计数": "6.5 × 10^9/L［参考值：4.5-11.0 × 10^9/L］", "血红蛋白": "86 g/L［参考值：120-160 g/L］", "血钙": "2.35 mmol/L［参考值：2.15-2.55 mmol/L］", "血钠": "140 mmol/L［参考值：136-145 mmol/L］", "血钾": "4.2 mmol/L［参考值：3.5-5.0 mmol/L］", "高密度脂蛋白胆固醇": "1.5 mmol/L［参考值：>1.2 mmol/L］"}, "status": "abnormal", "abnormal_indicators": ["红细胞压积", "红细胞计数", "血小板计数", "血红蛋白"]}}
